/*
  SpecularButton : ton composant d'origine (mêmes classes, mêmes variables CSS, même SCSS),
  mais avec UN SEUL contexte WebGL partagé par tous les boutons.

  Pourquoi : chaque bouton créait son propre contexte WebGL. Avec 7 boutons + les autres effets,
  Chrome mobile (limite d'environ 8) éjectait des effets de la page.
  Maintenant : un canvas caché fait le rendu, puis chaque bouton en copie le résultat
  dans son propre petit canvas 2D (qui prend la place de l'ancien canvas WebGL dans .specular-button__fx).

  Ce qui ne change PAS (ton SCSS continue de marcher tel quel) :
    - classes : specular-button, specular-button--lg, specular-button__fx, specular-button__label
    - variables CSS : --sb-radius, --sb-tint, --sb-tint-opacity, --sb-blur, --sb-text-color
    - toutes les options data-* (data-size, data-radius, data-line-color, data-intensity, data-auto-animate…)

  Ne PAS envelopper ce composant dans LazyGL : il partage déjà un seul contexte.
*/

// Marge du canvas autour du bouton, pour que la lueur déborde du bord
const PAD = 20;

const VERT = `#version 300 es
in vec2 position;
void main() {
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

const FRAG = `#version 300 es
precision highp float;

uniform vec2 uCenter;
uniform vec2 uHalfSize;
uniform float uRadius;
uniform float uAngle;
uniform float uPx;
uniform vec3 uLineColor;
uniform vec3 uBaseColor;
uniform float uIntensity;
uniform float uShineSize;
uniform float uShineFade;
uniform float uThickness;
uniform float uBaseWidth;

out vec4 fragColor;

float sdRoundedRect(vec2 p, vec2 b, float r) {
  vec2 q = abs(p) - b + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

float gaussianLine(float d, float sigma) {
  float x = d / (sigma + 1e-6);
  float k = mix(1.0, 1.6, smoothstep(0.0, 1.5, x));
  return exp(-k * x * x);
}

void main() {
  vec2 p = gl_FragCoord.xy - uCenter;
  float d = sdRoundedRect(p, uHalfSize, uRadius);
  vec2 L = vec2(cos(uAngle), sin(uAngle));

  // Trait de base sombre qui suit le bord
  float base = (1.0 - smoothstep(0.0, uBaseWidth, abs(d))) * 0.45;

  // Reflet spéculaire symétrique : les bords face à la lumière et à l'opposé brillent
  vec2 nEll = normalize(p / (uHalfSize * uHalfSize) + 1e-6);
  float phi = acos(clamp(abs(dot(nEll, L)), 0.0, 1.0));
  float rim = 1.0 - smoothstep(uShineSize - uShineFade, uShineSize + uShineFade + 1e-4, phi);
  float line = gaussianLine(d, uThickness);
  float edgeClamp = 1.0 - smoothstep(0.5 * uPx, 3.0 * uPx, abs(d));
  float hi = line * rim * edgeClamp * uIntensity;

  vec3 col = uBaseColor * base + uLineColor * hi;
  float a = clamp(base + hi, 0.0, 1.0);
  fragColor = vec4(col, a);
}
`;

const DEFAULTS = {
  size: 'lg',
  radius: 18,
  tint: '#ffffff',
  tintOpacity: 0,
  blur: 0,
  textColor: '#f5f5f5',
  lineColor: '#ffffff',
  baseColor: '#525252',
  intensity: 1,
  shineSize: 10,
  shineFade: 40,
  thickness: 1,
  speed: 0.35,
  followMouse: true,
  proximity: 250,
  autoAnimate: false,
};

/* ---------- Contexte WebGL partagé par tous les boutons ---------- */

let shared = null; // { canvas, gl, prog, vao, u, dead }
let users = 0; // nombre de boutons vivants

function createShared() {
  const canvas = document.createElement('canvas'); // jamais ajouté à la page
  canvas.width = 2;
  canvas.height = 2;
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false, // inutile : un seul triangle, le shader lisse déjà les bords
    depth: false,
    stencil: false,
  });
  if (!gl) return null;

  const compile = (type, src) => {
    const s = gl.createShader(type);
    gl.shaderSource(s, src);
    gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS))
      console.error(gl.getShaderInfoLog(s));
    return s;
  };
  const prog = gl.createProgram();
  gl.attachShader(prog, compile(gl.VERTEX_SHADER, VERT));
  gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, FRAG));
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
    console.error(gl.getProgramInfoLog(prog));
    return null;
  }

  // Un grand triangle qui couvre tout le canvas
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);
  const buf = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW,
  );
  const loc = gl.getAttribLocation(prog, 'position');
  gl.enableVertexAttribArray(loc);
  gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);

  const u = {};
  [
    'uCenter',
    'uHalfSize',
    'uRadius',
    'uAngle',
    'uPx',
    'uLineColor',
    'uBaseColor',
    'uIntensity',
    'uShineSize',
    'uShineFade',
    'uThickness',
    'uBaseWidth',
  ].forEach((n) => (u[n] = gl.getUniformLocation(prog, n)));

  gl.enable(gl.BLEND);
  gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
  gl.clearColor(0, 0, 0, 0);

  const sh = { canvas, gl, prog, vao, u, dead: false };
  // Si Chrome éjecte ce contexte, on en recrée un au prochain dessin
  canvas.addEventListener('webglcontextlost', (e) => {
    e.preventDefault();
    sh.dead = true;
    if (shared === sh) shared = null;
  });
  return sh;
}

function getShared() {
  if (shared && !shared.dead) return shared;
  shared = createShared();
  return shared;
}

function releaseShared() {
  users = Math.max(0, users - 1);
  if (users === 0 && shared) {
    shared.gl.getExtension('WEBGL_lose_context')?.loseContext();
    shared = null;
  }
}

// "#be7dfc" (ou toute couleur CSS) -> [r, g, b] entre 0 et 1
const toRGB = (color) => {
  const t = document.createElement('span');
  t.style.color = color;
  document.body.appendChild(t);
  const c = getComputedStyle(t).color;
  t.remove();
  return (c.match(/[\d.]+/g) || [255, 255, 255])
    .slice(0, 3)
    .map((n) => Number(n) / 255);
};

export default class SpecularButton {
  constructor(element) {
    this.el = element;
    if (!element || element.classList.contains('specular-button')) return;

    this.readOptions();
    this.buildDOM(); // toujours fait : le bouton garde son style même sans WebGL

    // WebGL2 requis pour l'effet : sinon le bouton reste un bouton normal
    if (!getShared()) {
      console.warn('SpecularButton : WebGL2 indisponible');
      return;
    }
    this.setup();
  }

  /* ---------- Lecture des options (identique à ton original) ---------- */

  readOptions() {
    const d = this.el.dataset;
    const num = (v, fallback) =>
      v === undefined || v === '' || Number.isNaN(parseFloat(v))
        ? fallback
        : parseFloat(v);
    const bool = (v, fallback) => (v === undefined ? fallback : v !== 'false');

    this.settings = {
      size: d.size || DEFAULTS.size,
      radius: num(d.radius, DEFAULTS.radius),
      tint: d.tint || DEFAULTS.tint,
      tintOpacity: num(d.tintOpacity, DEFAULTS.tintOpacity),
      blur: num(d.blur, DEFAULTS.blur),
      textColor: d.textColor || DEFAULTS.textColor,
      lineColor: d.lineColor || DEFAULTS.lineColor,
      baseColor: d.baseColor || DEFAULTS.baseColor,
      intensity: num(d.intensity, DEFAULTS.intensity),
      shineSize: num(d.shineSize, DEFAULTS.shineSize),
      shineFade: num(d.shineFade, DEFAULTS.shineFade),
      thickness: num(d.thickness, DEFAULTS.thickness),
      speed: num(d.speed, DEFAULTS.speed),
      followMouse: bool(d.followMouse, DEFAULTS.followMouse),
      proximity: num(d.proximity, DEFAULTS.proximity),
      // data-auto-animate sans valeur = activé
      autoAnimate:
        'autoAnimate' in d ? d.autoAnimate !== 'false' : DEFAULTS.autoAnimate,
    };
  }

  /* ---------- DOM : classes, variables CSS, calques (identique à ton original) ---------- */

  buildDOM() {
    const { el, settings: s } = this;

    el.classList.add('specular-button');
    if (s.size !== 'none') el.classList.add(`specular-button--${s.size}`);
    if (el.tagName === 'BUTTON' && !el.hasAttribute('type')) el.type = 'button';

    el.style.setProperty('--sb-radius', `${s.radius}px`);
    el.style.setProperty('--sb-tint', s.tint);
    el.style.setProperty('--sb-tint-opacity', s.tintOpacity);
    el.style.setProperty('--sb-blur', `${s.blur}px`);
    // backdrop-filter seulement si un flou est demandé (même à 0px il coûte du GPU)
    el.style.backdropFilter = s.blur > 0 ? `blur(${s.blur}px)` : '';
    el.style.webkitBackdropFilter = el.style.backdropFilter;
    el.style.setProperty('--sb-text-color', s.textColor);

    // Le contenu existant devient le libellé, au-dessus du canvas
    this.label = document.createElement('span');
    this.label.className = 'specular-button__label';
    this.label.append(...el.childNodes);

    this.fx = document.createElement('span');
    this.fx.className = 'specular-button__fx';
    this.fx.setAttribute('aria-hidden', 'true');

    el.append(this.fx, this.label);
  }

  /* ---------- Rendu : WebGL partagé -> copie dans un canvas 2D ---------- */

  setup() {
    const btn = this.el;
    const fx = this.fx;
    const s = this.settings;

    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    users++;

    // Le canvas 2D de CE bouton (à la place de l'ancien canvas WebGL)
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    fx.append(canvas);

    const lineRGB = toRGB(s.lineColor);
    const baseRGB = toRGB(s.baseColor);

    const reducedMotion =
      window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;

    let w = 1;
    let h = 1;
    let radius = s.radius;
    const resize = (entries) => {
      // Taille de mise en page (sans les transform: scale des parents, ex. le focus du carrousel),
      // fractionnaire quand le ResizeObserver la fournit, pour que le contour colle au bord CSS
      const box = entries?.[0]?.borderBoxSize?.[0];
      w = box ? box.inlineSize : btn.offsetWidth;
      h = box ? box.blockSize : btn.offsetHeight;
      if (!w || !h) return;
      // Rayon réel du CSS (au cas où le SCSS du projet surcharge border-radius)
      const cssRadius = parseFloat(getComputedStyle(btn).borderTopLeftRadius);
      radius = Number.isNaN(cssRadius) ? s.radius : cssRadius;
      canvas.width = Math.max(1, Math.round((w + PAD * 2) * dpr));
      canvas.height = Math.max(1, Math.round((h + PAD * 2) * dpr));
      start();
    };

    // La lumière s'oriente vers le curseur (n'importe où sur la page)
    let pointerAngle = null;
    let proximityT = 0;
    const onPointerMove = (e) => {
      const rect = btn.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const dx = Math.max(rect.left - e.clientX, 0, e.clientX - rect.right);
      const dy = Math.max(rect.top - e.clientY, 0, e.clientY - rect.bottom);
      const dist = Math.hypot(dx, dy);
      if (dist === 0) {
        // Sur le bouton : la lumière se pose en diagonale et ondule avec le curseur
        const nx = (e.clientX - cx) / (rect.width / 2);
        const ny = (cy - e.clientY) / (rect.height / 2);
        pointerAngle =
          Math.atan2(2 / rect.height, -2 / rect.width) + nx * 0.3 + ny * 0.15;
      } else {
        pointerAngle = Math.atan2(cy - e.clientY, e.clientX - cx);
      }
      const t = Math.max(0, 1 - dist / Math.max(s.proximity, 1));
      proximityT = t * t * (3 - 2 * t);
      start();
    };

    let angle = 2.4;
    let idleAngle = 2.4;
    let bright = 0;
    let last = performance.now();
    let raf = 0;
    let visible = false;
    let alive = true;

    const frame = (now) => {
      raf = 0;
      if (!alive || !visible || !w || !h) return;
      const dt = Math.min((now - last) / 1000, 0.05);
      last = now;

      if (!reducedMotion) idleAngle += s.speed * dt;
      const steer =
        s.followMouse &&
        pointerAngle != null &&
        (!s.autoAnimate || proximityT > 0);
      const target = steer ? pointerAngle : idleAngle;
      const diff = ((target - angle + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
      angle += diff * (1 - Math.exp(-dt * 7));

      // Le reflet apparaît avec la proximité du curseur, sauf si autoAnimate le garde allumé
      const brightTarget = s.autoAnimate ? 1 : proximityT;
      bright += (brightTarget - bright) * (1 - Math.exp(-dt * 8));

      draw();

      // On s'arrête quand tout est immobile (le reflet éteint ne bouge plus)
      const settled =
        !s.autoAnimate &&
        Math.abs(brightTarget - bright) < 0.001 &&
        (bright < 0.001 || (steer && Math.abs(diff) < 0.001));
      if (!settled) raf = requestAnimationFrame(frame);
    };

    // Dessine dans le contexte partagé, puis copie dans le canvas de ce bouton
    const draw = () => {
      const sh = getShared(); // recréé automatiquement si Chrome l'a éjecté
      if (!sh) return;
      const { gl, canvas: glCanvas, u } = sh;
      const cw = canvas.width;
      const ch = canvas.height;

      // Le canvas caché grandit au besoin (jamais réduit)
      if (glCanvas.width < cw || glCanvas.height < ch) {
        glCanvas.width = Math.max(glCanvas.width, cw);
        glCanvas.height = Math.max(glCanvas.height, ch);
      }

      gl.viewport(0, 0, cw, ch);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.useProgram(sh.prog);
      gl.bindVertexArray(sh.vao);

      gl.uniform2f(u.uCenter, (PAD + w / 2) * dpr, (PAD + h / 2) * dpr);
      gl.uniform2f(u.uHalfSize, (w / 2) * dpr, (h / 2) * dpr);
      gl.uniform1f(u.uRadius, Math.min(radius, Math.min(w, h) / 2) * dpr);
      gl.uniform1f(u.uAngle, angle);
      gl.uniform1f(u.uPx, dpr);
      gl.uniform3f(u.uLineColor, lineRGB[0], lineRGB[1], lineRGB[2]);
      gl.uniform3f(u.uBaseColor, baseRGB[0], baseRGB[1], baseRGB[2]);
      gl.uniform1f(u.uIntensity, s.intensity * bright);
      gl.uniform1f(u.uShineSize, (s.shineSize * Math.PI) / 180);
      gl.uniform1f(u.uShineFade, (s.shineFade * Math.PI) / 180);
      gl.uniform1f(u.uThickness, s.thickness * dpr);
      gl.uniform1f(u.uBaseWidth, dpr);
      gl.drawArrays(gl.TRIANGLES, 0, 3);

      // Copie immédiate. L'origine WebGL est en bas à gauche : la zone dessinée
      // est le coin bas-gauche du canvas caché, d'où le décalage en y.
      ctx.clearRect(0, 0, cw, ch);
      ctx.drawImage(glCanvas, 0, glCanvas.height - ch, cw, ch, 0, 0, cw, ch);
    };

    const start = () => {
      if (raf || !visible || !alive) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };

    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(btn);
    // Pause quand le bouton est hors écran ou caché (display: none)
    const intersectionObserver = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      start();
    });
    intersectionObserver.observe(btn);
    window.addEventListener('pointermove', onPointerMove, { passive: true });

    resize();

    this.destroy = () => {
      if (!alive) return;
      alive = false;
      cancelAnimationFrame(raf);
      resizeObserver.disconnect();
      intersectionObserver.disconnect();
      window.removeEventListener('pointermove', onPointerMove);
      canvas.remove();
      releaseShared();
    };
  }
}
